	atLine3(fl, 0, 1)
	atGroup(cg, refs, w0, 1, o0, 3, 0)
	atRun(cg, refs, fw, fl, et, feats, ow, im, ep, nfw, nfl, fv, fx, afa)
	port.AssertEq(emonT, player.FwCount(nfw), 3, "one word became three")
